package com.nyayaconnect.security;
import com.nyayaconnect.common.Api;import jakarta.servlet.*;import jakarta.servlet.http.*;import java.io.IOException;import java.security.SecureRandom;import java.util.Base64;import java.util.Set;
public class CsrfFilter implements Filter {public static final String SESSION_KEY="NYC_CSRF";private final SecureRandom random=new SecureRandom();
 public void doFilter(ServletRequest q,ServletResponse p,FilterChain c)throws IOException,ServletException{HttpServletRequest r=(HttpServletRequest)q;HttpServletResponse s=(HttpServletResponse)p;String method=r.getMethod();String path=r.getRequestURI().substring(r.getContextPath().length());if(!Set.of("POST","PUT","PATCH","DELETE").contains(method)||path.equals("/api/v1/auth/login")||path.equals("/api/v1/auth/register")||path.equals("/api/ai/triage")){c.doFilter(q,p);return;}HttpSession session=r.getSession(false);if(session==null||session.getAttribute(AuthenticationFilter.SESSION_KEY)==null){Api.error(s,401,"AUTH_REQUIRED","Authentication is required.");return;}String expected=(String)session.getAttribute(SESSION_KEY);String supplied=r.getHeader("X-CSRF-Token");if(expected==null||supplied==null||!constantTime(expected,supplied)){Api.error(s,403,"CSRF_FAILED","CSRF token is missing or invalid.");return;}c.doFilter(q,p);}
 public static String issue(){byte[] b=new byte[32];new SecureRandom().nextBytes(b);return Base64.getUrlEncoder().withoutPadding().encodeToString(b);}private static boolean constantTime(String a,String b){return java.security.MessageDigest.isEqual(a.getBytes(java.nio.charset.StandardCharsets.UTF_8),b.getBytes(java.nio.charset.StandardCharsets.UTF_8));}}
